Script:
.@r = getrefine();
bonus bBaseAtk,5;
bonus bMatkRate,1;
if (getiteminfo(getequipid(EQI_COMPOUND_ON), ITEMINFO_VIEW) == W_DAGGER) {
   if (.@r >= 7) {
      bonus bBaseAtk,20;
      bonus bMatkRate,2;
   }
   if (.@r >= 10) {
      bonus bBaseAtk,5;
      bonus bMatkRate,2;
   }
}

.@r = getrefine();
bonus bMatkRate,1;
bonus2 bMagicAtkEle,Ele_Earth,5;
bonus2 bSubRace,RC_Insect,5;
if (.@r >= 6) {
   bonus2 bSubRace,RC_Insect,5;
}

.@r = getrefine();
bonus bMatkRate,2;
bonus bMaxSPrate,4;
if (.@r >= 5) {
   bonus bMatkRate,2;
}
if (.@r >= 6) {
   bonus bMatkRate,1;
}
